(function(){
 const number=x=>Number(x)||0;
 const clean=x=>String(x||'').replace(/\s+/g,' ').trim().slice(0,100);
 resourceDeltaForm=function(g){
  const c=data.campaigns.find(c=>c.members?.some(m=>m.gangId===g.id)),member=c?.members.find(m=>m.gangId===g.id);
  let rows=[{key:'credits',label:'Credits',get:()=>number(g.credits),set:v=>g.credits=v},{key:'reputation',label:'Reputation',get:()=>number(g.reputation),set:v=>g.reputation=v}];
  if(String(g.edition).toUpperCase()==='N26')rows.push({key:'tradePoints',label:'Trade Points',get:()=>number(g.tradePoints),set:v=>g.tradePoints=v});
  for(const r of c?.resources||[])rows.push({key:r.id,label:r.name,get:()=>number(member.resources?.[r.id]),set:v=>{member.resources??={};member.resources[r.id]=v}});
  formModal('Resources','<p class="wide muted">Add or remove resources (e.g. 5 or -5)</p><div class="gc-resource-grid wide">'+rows.map(r=>`<label>${esc(r.label)} <small>(Current: ${fmt(r.get())})</small><input type="tel" inputmode="url" pattern="-?[0-9]+" name="delta_${esc(r.key)}" placeholder="0"><input class="gc-reason" name="reason_${esc(r.key)}" placeholder="Reason (optional)" maxlength="100" hidden></label>`).join('')+'</div><p class="gp-error wide" id="gc-error" role="alert"></p>',v=>{
   if(rows.some(r=>v['delta_'+r.key]&&!/^-?\d+$/.test(v['delta_'+r.key])))return false;
   if(number(g.credits)+number(v.delta_credits)<0){document.querySelector('#gc-error').textContent=`Insufficient credits. Current balance: ${fmt(g.credits)}`;return false}
   for(const r of rows){const delta=number(v['delta_'+r.key]);if(!delta)continue;const old=r.get();r.set(Math.max(0,old+delta));const reason=clean(v['reason_'+r.key]);log(g,`${r.label}: ${old} → ${r.get()}${reason?'\n'+reason:''}`);const entry=g.logs[0];entry.actionType=r.key==='credits'?(delta>0?'Credits earned':'Credits spent'):r.key==='reputation'?(delta>0?'Reputation gained':'Reputation lost'):'Resource changed'}save();
  },'Save Changes');
  document.querySelector('#modal-form').addEventListener('input',e=>{if(e.target.name?.startsWith('delta_')){const reason=document.querySelector('#modal-form').elements['reason_'+e.target.name.slice(6)];reason.hidden=!number(e.target.value)}});
 };
 function logType(x){if(x.actionType)return x.actionType;if(x.action_type)return x.action_type.replaceAll('_',' ');let t=x.text||x.description||'';if(/XP/i.test(t))return 'XP changed';if(/injur/i.test(t))return 'Fighter injured';if(/equipment|purchased/i.test(t))return 'Equipment purchased';if(/recruit|fighter.*added/i.test(t))return 'Fighter added';if(/tactic/i.test(t))return 'Gang Tactic changed';if(/gang created/i.test(t))return 'Gang created';return 'Gang updated'}
 function logs(g,initial={}){
  let state={type:'',fighter:'',vehicle:'',page:1,...initial};
  showModal(initial.fighter?'Fighter Logs':'Gang Logs','<div id="gc-log-content"></div>','Close',()=>true);document.querySelector('#modal-cancel').hidden=true;
  function draw(){const focused=document.activeElement,focusName=focused?.closest('[data-mm-combo]')?.querySelector('input[type=hidden]')?.name,body=document.querySelector('.modal-body'),scrollTop=body?.scrollTop||0;const all=(g.logs||[]).filter(x=>(!state.fighter||x.fighterId===state.fighter||x.fighter_id===state.fighter||(x.text||'').includes(g.fighters.find(f=>f.id===state.fighter)?.name||'\u0000'))&&(!state.vehicle||x.vehicleId===state.vehicle||x.vehicle_id===state.vehicle||(x.text||'').includes(g.vehicles?.find(v=>v.id===state.vehicle)?.name||'\u0000'))).slice(0,100),types=[...new Set(all.map(logType))].sort(),filtered=all.filter(x=>!state.type||logType(x)===state.type),pages=Math.max(1,Math.ceil(filtered.length/10));state.page=Math.min(state.page,pages);const from=(state.page-1)*10,combo=MMWidgets.combo;document.querySelector('#gc-log-content').innerHTML='<h3>Filters</h3><div class="gc-log-filters">'+combo('logType','Action Type',[{value:'',label:'All Action Types'},...types.map(t=>({value:t,label:t}))],state.type,'All Action Types')+(!initial.fighter&&g.fighters.length?combo('logFighter','Fighter',[{value:'',label:'All Fighters'},...g.fighters.map(f=>({value:f.id,label:f.name}))],state.fighter,'All Fighters'):'')+((g.vehicles||[]).length?combo('logVehicle','Vehicle',[{value:'',label:'All Vehicles'},...g.vehicles.map(v=>({value:v.id,label:v.name||v.type}))],state.vehicle,'All Vehicles'):'')+'</div>'+((state.type||state.fighter||state.vehicle)&&!initial.fighter?`<div class="section-heading"><small>Showing ${filtered.length} of ${all.length} logs</small><button class="btn small" data-gc-log="clear">× Clear</button></div>`:'')+'<div class="table-wrap gc-log-table"><table><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>User</th></tr></thead><tbody>'+filtered.slice(from,from+10).map(x=>`<tr><td>${esc(new Date(x.at||x.created_at).toLocaleString('sv-SE').slice(0,16).replace(' ',' — '))}</td><td>${esc(logType(x))}</td><td>${esc(x.text||x.description||'')}</td><td>${esc(x.username||window.AccountParity?.account?.username||'System')}</td></tr>`).join('')+(filtered.length?'':'<tr><td colspan="4">'+(all.length?'No logs match the selected filters.':'No activity logs found.')+'</td></tr>')+'</tbody></table></div>'+(pages>1?`<div class="gc-log-pages"><small>Logs ${from+1} to ${Math.min(from+10,filtered.length)} of ${filtered.length}</small><button class="btn small" data-gc-log="prev" ${state.page===1?'disabled':''}>Prev</button>${Array.from({length:pages},(_,i)=>`<button class="btn small ${state.page===i+1?'primary':''}" data-gc-page="${i+1}">${i+1}</button>`).join('')}<button class="btn small" data-gc-log="next" ${state.page===pages?'disabled':''}>Next</button></div>`:'');
   if(focusName)document.querySelector('#gc-log-content [name="'+focusName+'"]')?.closest('[data-mm-combo]')?.querySelector('[data-mm-trigger]')?.focus({preventScroll:true});if(body)body.scrollTop=scrollTop;
  }draw();const content=document.querySelector('#gc-log-content');content.addEventListener('change',e=>{const field={logType:'type',logFighter:'fighter',logVehicle:'vehicle'}[e.target.name];if(field){state[field]=e.target.value;state.page=1;draw()}});content.addEventListener('click',e=>{const t=e.target.closest('[data-gc-log],[data-gc-page]');if(!t)return;if(t.dataset.gcPage)state.page=number(t.dataset.gcPage);else if(t.dataset.gcLog==='clear')state={type:'',fighter:'',vehicle:'',page:1};else state.page+=t.dataset.gcLog==='next'?1:-1;draw()});
 }
 function toast(text){document.querySelector('.gc-toast')?.remove();const el=document.createElement('div');el.className='gc-toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),3000)}
 async function share(g){const url=location.origin+'/gang/'+encodeURIComponent(g.id);try{if(navigator.share)await navigator.share({title:g.name,url});else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('Link copied to clipboard!')}else{const input=document.createElement('textarea');input.value=url;input.readOnly=true;input.setAttribute('inputmode','none');Object.assign(input.style,{position:'fixed',opacity:'0',left:'-9999px'});document.body.append(input);input.select();const result=document.execCommand('copy');input.remove();toast(result?'Link copied to clipboard!':'Failed to copy link.')}}catch(e){if(e.name!=='AbortError')toast('Failed to copy link.')}}
 window.addEventListener('click',e=>{const t=e.target.closest('[data-gp="logs"],[data-gp="share-gang"],[data-gc="fighter-logs"]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();if(t.dataset.gp==='share-gang')share(gang());else logs(gang(),t.dataset.gc?{fighter:currentFighter()?.id}:{})},true);
 const previous=render;render=function(){previous();if(data.view==='fighter'){const actions=document.querySelector('.fighter-page-actions');if(actions&&!actions.querySelector('[data-gc]'))actions.insertAdjacentHTML('beforeend','<button class="btn" data-gc="fighter-logs" aria-label="View Fighter Logs" title="View Fighter Logs">☷</button>')}};
 window.MMGangControls={logs,share};
})();
